<?php
namespace App\Http\Resources;
use Illuminate\Http\Request;use Illuminate\Http\Resources\Json\JsonResource;
class TrainingSessionResource extends JsonResource { public function toArray(Request $request): array { return ['id'=>$this->id,'athlete_id'=>$this->athlete_id,'training_type_id'=>$this->training_type_id,'title'=>$this->title,'description'=>$this->description,'session_date'=>$this->session_date?->toDateString(),'start_time'=>$this->start_time,'end_time'=>$this->end_time,'location'=>$this->location,'intensity'=>$this->intensity,'status'=>$this->status,'duration_minutes'=>$this->duration_minutes,'perceived_exertion'=>$this->perceived_exertion,'distance_km'=>$this->distance_km,'athlete_notes'=>$this->athlete_notes,'coach_feedback'=>$this->coach_feedback,'reviewed_at'=>$this->reviewed_at,'athlete'=>new AthleteResource($this->whenLoaded('athlete')),'training_type'=>new TrainingTypeResource($this->whenLoaded('trainingType')),'creator'=>new UserResource($this->whenLoaded('creator')),'reviewer'=>new UserResource($this->whenLoaded('reviewer'))]; } }
